import {learnerLine} from './learner-voice.js?v=20261106d';
import {cartoonCast as cast, plantDrawing, leafDrawing} from './factory-art.js?v=20261106d';
import {icon,title,next,complete,state,escapeHTML} from './app.js?v=20261106d';
const demo = [
  {focus:'water', who:'Water', line:'Up we go! Roots absorb water. It travels inside the stem and into the veins of the leaves. Follow the blue route!', seconds:9},
  {focus:'air', who:'Sprout', line:'Carbon dioxide is a gas in the air. It enters through tiny openings in a leaf.', seconds:9},
  {focus:'light', who:'Sprout', line:'Watch the cloud move away. Sunlight can now reach the leaf.', seconds:6},
  {focus:'chlorophyll', who:'Sprout', line:'Chlorophyll is the green substance in plants. It absorbs sunlight. Look at the green parts inside this enlarged leaf!', seconds:10}
];
const focusLabels={water:'BLUE WATER ROUTE',air:'TINY LEAF OPENING',light:'THE SUN',chlorophyll:'GREEN CHLOROPLASTS'};
const demoTitles=['Water travels up the plant','Carbon dioxide enters the leaf','Sunlight reaches the leaf','Chlorophyll absorbs light'];
const demoHints=['Start at the circled root. Follow the blue drop up to the leaf.','This is a close-up of the selected leaf. Watch the circled opening underneath it.','Look at the circled Sun. Watch the cloud move away.','Now look inside that same leaf. Chlorophyll in these green ovals absorbs light energy.'];

const $=s=>document.querySelector(s);
let step=0,loop,elapsed=0,lastTick=0,started=false,paused=false,phase='video';
function cancel(){clearInterval(loop);loop=null}
export function cleanupFactory(){cancel();document.removeEventListener('visibilitychange',onVisibility);$('#settings')?.removeEventListener('click',onSettings)}
function say(who,text){$('#factory-speaker').textContent=who;$('#factory-line').textContent=text;$('#guide-face').innerHTML=cast(who==='Water'?'drop':'sprout')}
function needsDrawing(){return leafDrawing().replace(/<path class="oxygen-stream"[^>]*\/>/g,'').replace(/<g class="(?:oxygen-symbol|food-symbol|demo-cue cue-products)"[\s\S]*?<\/g>/g,'').replace(' Oxygen exits into the air.','').replace('Green pigment in chloroplasts','Green substance in plants').replace('inside leaf cells.','absorbs sunlight.')}
function stage(){return `<div class="leaf-workshop svg-workshop demonstrating is-waiting" id="leaf-workshop" data-focus="${demo[step].focus}"><div class="science-scenes"><section class="plant-panel" aria-label="The whole plant"><div class="scene-heading"><span class="scene-number">1</span><div><b>Follow the water</b><small>Roots → stem → leaf</small></div></div>${plantDrawing()}</section><section class="leaf-panel" aria-label="A closer look at the same leaf"><div class="scene-heading"><span class="scene-number">2</span><div><b>A closer look</b><small>A slice through that same leaf</small></div></div>${needsDrawing()}</section></div><div id="factory-status" class="science-status" role="status">Press Start when you are ready.</div></div>`}
export function factory(){return title('story','What does Sprout need?','Chapter 2 · Explore water, carbon dioxide, sunlight and chlorophyll. Products come in the next chapter.')+`<section class="leaf-experience guided-factory needs-only"><div class="experience-bar"><div class="episode-tags"><span id="chapter-film">Four needs</span><span id="chapter-demo" class="active">Inside the leaf</span></div></div><div class="factory-narrator"><div id="guide-face">${cast('sprout')}</div><div class="narrator-caption" aria-live="polite" aria-atomic="true"><div class="narrator-meta"><b id="factory-speaker">Sprout</b><span id="factory-look" class="narrator-look" hidden>LOOK AT: <span id="factory-look-text"></span>${icon('arrow')}</span></div><p id="factory-line"></p></div></div><div id="factory-visual"></div><div class="episode-progress" aria-hidden="true"><span id="episode-progress"></span></div></section><details class="transcript"><summary>The four needs · picture notes</summary>${demo.map(x=>`<p>${x.line}</p>`).join('')}<p>Chlorophyll is already inside the plant. Sunlight reaches it; water enters through roots; carbon dioxide enters leaves from the air.</p><p class="caption">Science Year 4 · printed page 77. The enlarged leaf is a model.</p></details>`+next('story','Play Collect & Avoid',true)}
export function bindFactory(){cleanupFactory();step=0;document.addEventListener('visibilitychange',onVisibility);$('#settings')?.addEventListener('click',onSettings);showStep()}
function onVisibility(){if(document.hidden&&phase==='lesson'&&started&&!paused)pause()}
function onSettings(){if(phase==='lesson'&&started&&!paused)pause()}
function pause(){paused=!paused;$('.leaf-experience').classList.toggle('is-paused',paused);$('#lesson-pause').textContent=paused?'Resume':'Pause';lastTick=performance.now()}
function apply(index){const s=$('#leaf-workshop');if(index===0)s.classList.add('water-arrived');if(index===1)s.classList.add('gas-arrived');if(index===2){s.style.setProperty('--sunlight',1);s.classList.add('light-arrived')}if(index===4)s.classList.add('is-making');if(index===5){s.classList.remove('is-making');s.classList.add('has-products')}}
function showStep(autoStart=false){cancel();phase='lesson';started=false;paused=false;elapsed=0;$('.leaf-experience').classList.remove('is-paused');$('.factory-narrator').hidden=false;$('#chapter-film').classList.remove('active');$('#chapter-demo').classList.add('active');$('#factory-look').hidden=true;$('#episode-progress').style.width=(step/demo.length*100)+'%';$('#factory-visual').innerHTML=`<div class="demo-controls" id="demo-controls"><div><h2 id="demo-title" tabindex="-1">Step ${step+1} of ${demo.length} · ${demoTitles[step]}</h2><p id="demo-instruction">Press Start once to begin. Next starts the following step.</p></div><div class="demo-buttons"><button id="lesson-start" class="btn yellow">${icon('play')} Start this step</button><button id="lesson-pause" class="text-btn" hidden>Pause</button><button id="lesson-next" class="btn yellow" data-local-forward="true" data-label="${step===demo.length-1?'Next: finish lesson':'Next step'}" disabled>Next step ${icon('arrow')}</button></div></div>${stage()}`;for(let i=0;i<step;i++)apply(i);$('#factory-line').textContent=learnerLine('Ready, {name}? Start this step to see what happens.','Start this step to see what happens.');$('#factory-speaker').textContent='Sprout';$('#lesson-start').onclick=startStep;$('#lesson-pause').onclick=pause;$('#lesson-next').onclick=()=>{cancel();if(step===demo.length-1)finish();else{step++;showStep(true)}};$('#demo-title').focus({preventScroll:true});$('.leaf-experience').scrollIntoView({block:'start',behavior:'instant'});if(autoStart)startStep()}
function startStep(){cancel();started=true;paused=false;elapsed=0;$('.leaf-experience').classList.remove('is-paused');const s=$('#leaf-workshop');s.classList.remove('is-waiting','lesson-settled');$('#lesson-next').disabled=false;$('#lesson-start').innerHTML=icon('play')+' Replay step';$('#lesson-pause').hidden=false;$('#lesson-pause').textContent='Pause';$('#demo-instruction').textContent=demoHints[step];$('#factory-look-text').textContent=focusLabels[demo[step].focus];$('#factory-look').hidden=false;say(demo[step].who,demo[step].line);$('#factory-status').textContent=demo[step].line;if(step===2){s.style.setProperty('--sunlight',0);s.classList.remove('light-arrived')}lastTick=performance.now();animate();loop=setInterval(()=>{const now=performance.now();if(!paused){elapsed+=(now-lastTick)/1000;animate();if(elapsed>=6){clearInterval(loop);loop=null;s.classList.add('lesson-settled');$('#lesson-pause').hidden=true;$('#demo-instruction').textContent='Take your time. Replay this step or use Next when you’re ready.';$('#episode-progress').style.width=((step+1)/demo.length*100)+'%'}}lastTick=now},40)}
function animate(){const progress=Math.min(1,elapsed/5);const reduced=state.settings.motion||matchMedia('(prefers-reduced-motion: reduce)').matches;apply(step);if(step===0||step===1){const path=$(step===0?'#water-route':'#demo-gas-route'),dot=$(step===0?'#water-traveller':'#carbon-traveller'),p=path.getPointAtLength(path.getTotalLength()*(reduced?1:progress));dot.setAttribute('r',step===0?'9':'10');dot.setAttribute('transform',`translate(${p.x} ${p.y})`);dot.setAttribute('visibility',progress<1&&!reduced?'visible':'hidden')}if(step===2){$('#leaf-workshop').style.setProperty('--sunlight',reduced?1:progress);$('#leaf-workshop').classList.toggle('light-arrived',reduced||progress===1)}}
function finish(){cancel();phase='finished';$('.leaf-experience').classList.remove('is-paused');$('#factory-visual').innerHTML=`<div class="demo-intro"><h2 tabindex="-1">Four needs, ready to remember!</h2><p>Sunlight, water, carbon dioxide and chlorophyll.</p><p>Now help Sprout collect the four needs in Collect & Avoid.</p></div>${stage()}`;for(let i=0;i<demo.length;i++)apply(i);$('#leaf-workshop').classList.add('lesson-settled');$('#factory-status').textContent='Sunlight · water · carbon dioxide · chlorophyll';$('#factory-look').hidden=true;say('Sprout','You have explored all four needs. Which ones can you remember?');$('#episode-progress').style.width='100%';complete('story');$('#factory-visual h2').focus({preventScroll:true})}
